create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,role text default 'owner',is_blocked boolean default false,created_at timestamptz default now());
create table if not exists businesses(id uuid primary key default gen_random_uuid(),owner_id uuid references auth.users(id) on delete cascade,name text not null,slug text unique,category text,tagline text,phone text,whatsapp text,address text,about text,logo_url text,status text default 'Active',created_at timestamptz default now());
create table if not exists products(id uuid primary key default gen_random_uuid(),business_id uuid references businesses(id) on delete cascade,name text not null,price numeric default 0,description text,image_url text,created_at timestamptz default now());
create table if not exists services(id uuid primary key default gen_random_uuid(),business_id uuid references businesses(id) on delete cascade,name text not null,price numeric default 0,description text,image_url text,created_at timestamptz default now());
create table if not exists orders(id uuid primary key default gen_random_uuid(),business_id uuid references businesses(id) on delete cascade,customer_id uuid references auth.users(id) on delete set null,customer_name text,item_name text,amount numeric default 0,status text default 'Pending',created_at timestamptz default now());
create table if not exists appointments(id uuid primary key default gen_random_uuid(),business_id uuid references businesses(id) on delete cascade,customer_id uuid references auth.users(id) on delete set null,customer_name text,service_name text,appointment_date date,appointment_time text,message text,status text default 'Pending',created_at timestamptz default now());
alter table businesses add column if not exists category text;alter table businesses add column if not exists tagline text;alter table businesses add column if not exists phone text;alter table businesses add column if not exists whatsapp text;alter table businesses add column if not exists address text;alter table businesses add column if not exists about text;alter table businesses add column if not exists logo_url text;alter table businesses add column if not exists status text default 'Active';alter table businesses add column if not exists slug text;
alter table profiles enable row level security;alter table businesses enable row level security;alter table products enable row level security;alter table services enable row level security;alter table orders enable row level security;alter table appointments enable row level security;
drop policy if exists profiles_all on profiles;create policy profiles_all on profiles for all to authenticated using(id=auth.uid() or exists(select 1 from profiles p where p.id=auth.uid() and p.role='admin')) with check(id=auth.uid() or exists(select 1 from profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists business_read on businesses;create policy business_read on businesses for select using(status='Active' or owner_id=auth.uid() or exists(select 1 from profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists business_write on businesses;create policy business_write on businesses for all to authenticated using(owner_id=auth.uid() or exists(select 1 from profiles p where p.id=auth.uid() and p.role='admin')) with check(owner_id=auth.uid() or exists(select 1 from profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists product_read on products;create policy product_read on products for select using(true);drop policy if exists product_write on products;create policy product_write on products for all to authenticated using(exists(select 1 from businesses b where b.id=business_id and b.owner_id=auth.uid())) with check(exists(select 1 from businesses b where b.id=business_id and b.owner_id=auth.uid()));
drop policy if exists service_read on services;create policy service_read on services for select using(true);drop policy if exists service_write on services;create policy service_write on services for all to authenticated using(exists(select 1 from businesses b where b.id=business_id and b.owner_id=auth.uid())) with check(exists(select 1 from businesses b where b.id=business_id and b.owner_id=auth.uid()));
drop policy if exists order_insert on orders;create policy order_insert on orders for insert with check(true);drop policy if exists order_read on orders;create policy order_read on orders for select to authenticated using(customer_id=auth.uid() or exists(select 1 from businesses b where b.id=business_id and b.owner_id=auth.uid()) or exists(select 1 from profiles p where p.id=auth.uid() and p.role='admin'));
drop policy if exists appointment_insert on appointments;create policy appointment_insert on appointments for insert with check(true);drop policy if exists appointment_read on appointments;create policy appointment_read on appointments for select to authenticated using(customer_id=auth.uid() or exists(select 1 from businesses b where b.id=business_id and b.owner_id=auth.uid()) or exists(select 1 from profiles p where p.id=auth.uid() and p.role='admin'));
insert into storage.buckets(id,name,public) values('business-media','business-media',true) on conflict(id) do nothing;
drop policy if exists media_read on storage.objects;create policy media_read on storage.objects for select using(bucket_id='business-media');drop policy if exists media_insert on storage.objects;create policy media_insert on storage.objects for insert to authenticated with check(bucket_id='business-media');
